Subroutine Promedio(a As Integer, b As Integer) As Real
  Return (a + b) / 2;
EndSubroutine

Subroutine Estado(promedio As Real) As String
  If promedio >= 6 Then
    Return "aprobado";
  EndIf
  Return "desaprobado";
EndSubroutine

Algorithm Boletin
  Define nombre As String;
  Define n1, n2 As Integer;
  Define mejorNombre As String <- "";
  Define mejorPromedio As Real <- -1.0;
  For i <- 1 To 3 Do
    Read nombre;
    Read n1;
    Read n2;
    Define p As Real <- Promedio(n1, n2);
    Write nombre, ": ", p, " ", Estado(p);
    If p > mejorPromedio Then
      mejorPromedio <- p;
      mejorNombre <- nombre;
    EndIf
  EndFor
  Write "Mejor promedio: ", mejorNombre;
EndAlgorithm
